#include "search.h"
#include "../v8-search/mcts.h"
using namespace v2;
int main(int argc,char**argv){try{if(argc!=7)throw std::runtime_error("NET_OR_BASE MODE SEED N MS OUTPUT");init();Learner m;m.load("training/v7/base.ntd");v9::Net student;bool baseline=std::string(argv[1])=="base";if(!baseline)student.load(argv[1]);std::string mode=argv[2];MCTS mc(m);RootPolicySearch learned(m,student);double budget=std::stod(argv[5])/1000;mc.budget=learned.budget=budget;uint32_t first=std::stoul(argv[3]);int n=std::stoi(argv[4]);std::ofstream out(argv[6]);out<<std::setprecision(17);for(int i=0;i<n;i++){RNG rng{first+uint32_t(i)};Game g;g.reset(rng);Counts c=opening(g);double sumTime=0,maxTime=0;int overruns=0,depths[10]{},maxDepth=0;uint64_t work=0;auto begin=cpuNow();while(!g.over&&high(g.b)<12&&g.turns<6000){double start=cpuNow();Answer a;int depth;uint32_t searchSeed=uint32_t((first+i)*2654435761u)^uint32_t(g.turns*2246822519u);if(baseline){a=mc.choose(g.b,g.next,c,searchSeed);depth=mc.maxReached;work+=mc.simulations;}else{a=learned.choose(g.b,g.next,c,searchSeed);depth=learned.maxReached;work+=learned.simulations;}double elapsed=cpuNow()-start;sumTime+=elapsed;maxTime=std::max(maxTime,elapsed);overruns+=elapsed>budget*1.2;depths[std::min(9,depth)]++;maxDepth=std::max(maxDepth,depth);auto moved=move(g.b,a.direction);if(a.direction<0||!moved.size)throw std::runtime_error("illegal move");g.advance(moved,rng);c=observe(c,g.next);}if(!g.over&&high(g.b)<12)throw std::runtime_error("truncated");out<<"{\"seed\":"<<first+i<<",\"success\":"<<(high(g.b)>=12?"true":"false")<<",\"moves\":"<<g.turns<<",\"cpu\":"<<cpuNow()-begin<<",\"searchCPU\":"<<sumTime<<",\"maxMoveCPU\":"<<maxTime<<",\"overruns20pct\":"<<overruns<<",\"work\":"<<work<<",\"depths\":[";for(int j=0;j<10;j++)out<<(j?",":"")<<depths[j];out<<"]}"<<std::endl;}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
